        Ok(Ok(0)) => return,
        Ok(Ok(_)) => match serde_json::from_str::<Hello>(hello_line.trim()) {
            Ok(hello) => hello.kind,
            Err(_) => return, // Hello でない・不正な kind: 切断
        },
        Ok(Err(_)) => return,
        Err(_) => return, // 無言接続: タイムアウトで切断
